const scope=new URL('./',self.location.href);
const corePaths=new Set(CORE.map(file=>new URL(file,scope).pathname));
let mediaWrites=Promise.resolve();

self.addEventListener('install',event=>{
 event.waitUntil(caches.open(CORE_CACHE).then(cache=>cache.addAll(CORE.map(file=>new Request(new URL(file,scope),{cache:'reload'})))).then(async()=>{
  // v8 clients have no update button; migrate them after this release is complete.
  if((await caches.keys()).includes(PREFIX+'v8'))await self.skipWaiting();
 }));
});
self.addEventListener('activate',event=>{
 event.waitUntil((async()=>{
  const keys=await caches.keys(),legacy=keys.includes(PREFIX+'v8');
  await Promise.all(keys.filter(key=>key.startsWith(PREFIX)&&![CORE_CACHE,MEDIA_CACHE].includes(key)).map(key=>caches.delete(key)));
  await self.clients.claim();
  if(legacy)for(const client of await self.clients.matchAll({type:'window'}))if(new URL(client.url).pathname.startsWith(scope.pathname))await client.navigate(client.url);
 })());
});

function cacheMedia(request,response){
 mediaWrites=mediaWrites.catch(()=>{}).then(async()=>{
  const cache=await caches.open(MEDIA_CACHE);await cache.put(request,response);
  const keys=await cache.keys();await Promise.all(keys.slice(0,Math.max(0,keys.length-MEDIA_LIMIT)).map(key=>cache.delete(key)));
 });
 return mediaWrites;
}
async function rangeResponse(request,response){
 const range=request.headers.get('range');if(!range)return response;
 const match=/^bytes=(\d*)-(\d*)$/.exec(range);if(!match)return response;
 const body=await response.blob(),size=body.size;
 const start=match[1]?Number(match[1]):Math.max(0,size-Number(match[2]));
 const end=match[1]&&match[2]?Math.min(Number(match[2]),size-1):size-1;
 if(start>end||start>=size)return new Response(null,{status:416,headers:{'Content-Range':`bytes */${size}`}});
 const headers=new Headers(response.headers);headers.set('Content-Range',`bytes ${start}-${end}/${size}`);headers.set('Content-Length',String(end-start+1));headers.set('Accept-Ranges','bytes');
 return new Response(body.slice(start,end+1),{status:206,headers});
}
self.addEventListener('fetch',event=>{
 const request=event.request,url=new URL(request.url);
 if(request.method!=='GET'||url.origin!==scope.origin||!url.pathname.startsWith(scope.pathname))return;
 event.respondWith((async()=>{
  // HTML and modules come from one installed release until an update is accepted.
  const core=await caches.open(CORE_CACHE);
  const cached=await core.match(request.mode==='navigate'?new URL('index.html',scope):url,{ignoreSearch:true});
  if(cached&&(request.mode==='navigate'||corePaths.has(url.pathname)))return rangeResponse(request,cached);
  const media=await caches.open(MEDIA_CACHE),asset=await media.match(request,{ignoreSearch:true});
  if(asset)return rangeResponse(request,asset);
  try{
   // Fetch a complete audio file so cached playback also supports iOS Range requests.
   const headers=new Headers(request.headers);headers.delete('range');
   const response=await fetch(new Request(request,{headers}));
   if(response.ok&&response.status===200){const copy=response.clone();event.waitUntil(cacheMedia(new Request(url),copy).catch(()=>{}));}
   return rangeResponse(request,response);
  }catch{return new Response('此内容尚未下载，联网后再试。',{status:503,headers:{'Content-Type':'text/plain; charset=utf-8'}});}
 })());
});
self.addEventListener('message',event=>{
 if(event.data?.type==='SKIP_WAITING'){self.skipWaiting();return;}
 if(event.data?.type!=='CACHE_VISITED')return;
 event.waitUntil((async()=>{
  let complete=true;
  for(const value of (Array.isArray(event.data.urls)?event.data.urls:[]).slice(0,160)){
   try{
    const url=new URL(value,scope);if(url.origin!==scope.origin||!url.pathname.startsWith(new URL('assets/',scope).pathname))continue;
    if(await caches.match(url,{ignoreSearch:true}))continue;
    const response=await fetch(url);if(!response.ok){complete=false;continue;}await cacheMedia(new Request(url),response);
   }catch{complete=false;}
  }
  event.ports[0]?.postMessage({complete});
 })());
});
